import { z } from 'zod';

/** Public IDs are UUIDs (UUIDv7 when the server mints them). A client-generated command ID is any UUID. */
export const UuidSchema = z.uuid();

/** Generated by the client once per user intent and reused on every retry of that intent. */
export const CommandIdSchema = z.uuid();
export const AssetIdSchema = z.uuid();
export const UniverseIdSchema = z.uuid();
